// The Sunken Vault, a level for examples/tremor.psh
//
// Brushes are convex solids; the space you walk through is what is left
// between them. Coordinates are in meters. A texture tiles at 40 texels per
// meter by default, so a 256-texel texture repeats every 6.4 m. Rooms are
// sized in multiples of 1.6 m. A texture is loaded the first time its name is
// used below; nothing needs declaring up front.
//
//   area  <name> { ... }
//   spawn x= y= z= yaw=<degrees>
//   tour  x= y= z= yaw=<degrees> pitch=<degrees>
//   light x= y= z= radius= brightness=
//   box   x0= y0= z0= x1= y1= z1= [keys]
//   ramp  x0= y0= z0= x1= y1= z1= dir=<px|nx|pz|nz> [keys]
//   prism cx= cz= radius= y0= y1= sides= rot=<degrees> [keys]
//   arch  axis=<x|z> a0= a1= c0= c1= ybase= ytop= segs= [keys]
//   portal to=<area> x0= y0= z0= x1= y1= z1= dir=<px|nx|py|ny|pz|nz>
//                    [yaw=<degrees>] [dx= dy= dz=]
//
// Keys: tex= side= top= bottom= nx= px= ny= py= nz= pz= name the texture to
// place on a face, light=<0..15> to force a light level instead of baking one,
// scale=<f> sets the texture density in texels per meter (default 40, so
// scale=20 makes a texture repeat over twice the span),
// fit to stretch a texture once across each face, flow to make it swim and
// burn at full brightness whatever is around it,
// turn to give the texture a quarter turn on the face.
//
// --- Areas ---
//
// The level is six rooms, each an area of its own: the renderer draws the one
// the player stands in, and reaches the rest only through the portals that join
// them. A portal is a rectangle with no thickness along the axis `dir` runs on,
// `dir` being the way through it. It is one way, so a doorway is a pair.
//
// Every area is closed on its own. Where two of them meet, both carry the whole
// wall the doorway is cut through -- the same boxes and the same arch, written
// out twice -- and each one's portal stands on the far face of that wall, where
// the next room begins. The wall is then nearer than the portal it surrounds,
// so the tree draws it first and the s-buffer knows the true shape of the
// opening by the time the portal asks whether anything of it shows. The other
// room's copy stands on the eye's side of that plane and is dropped.
//
// Light is an area's own: it comes from the lamps listed inside it and is
// stopped by the solids listed inside it, and none of it passes a portal. A
// lamp near a doorway is therefore written into both rooms, so that the two
// copies of the wall between them come out lit the same and the seam does not
// show as you walk through.
//
// Nothing here is lit by hand except the fixtures themselves: every other
// surface takes its light from the lamps, so the rooms go dark wherever the
// lamps do not reach.

// ===========================================================================
// Entry crypt: interior x -4.8..4.8, z -17.6..-6.4, floor 0, ceiling 5.6
// ===========================================================================

area crypt {
    spawn x=0 y=1.4 z=-13 yaw=0

    box   x0=-6.4 y0=-0.8 z0=-19.2 x1=6.4 y1=0 z1=-4.8 tex=floor_stone
    box   x0=-6.4 y0=5.6 z0=-19.2 x1=6.4 y1=6.4 z1=-4.8 tex=stone_large
    box   x0=-6.4 y0=0 z0=-19.2 x1=6.4 y1=5.6 z1=-17.6 tex=stone_blocks

    // West wall, with a torch niche cut into it at z -14..-12.4
    box   x0=-6.4 y0=0 z0=-19.2 x1=-4.8 y1=5.6 z1=-14 tex=stone_blocks
    box   x0=-6.4 y0=0 z0=-12.4 x1=-4.8 y1=5.6 z1=-4.8 tex=stone_blocks
    box   x0=-6.4 y0=0 z0=-14 x1=-4.8 y1=2.4 z1=-12.4 tex=stone_blocks
    box   x0=-6.4 y0=4 z0=-14 x1=-4.8 y1=5.6 z1=-12.4 tex=stone_blocks
    box   x0=-6.4 y0=2.4 z0=-14 x1=-5.6 y1=4 z1=-12.4 tex=stone_blocks px=light_bank light=15 fit

    // East wall, with the same niche mirrored
    box   x0=4.8 y0=0 z0=-19.2 x1=6.4 y1=5.6 z1=-14 tex=stone_blocks
    box   x0=4.8 y0=0 z0=-12.4 x1=6.4 y1=5.6 z1=-4.8 tex=stone_blocks
    box   x0=4.8 y0=0 z0=-14 x1=6.4 y1=2.4 z1=-12.4 tex=stone_blocks
    box   x0=4.8 y0=4 z0=-14 x1=6.4 y1=5.6 z1=-12.4 tex=stone_blocks
    box   x0=5.6 y0=2.4 z0=-14 x1=6.4 y1=4 z1=-12.4 tex=stone_blocks nx=light_bank light=15 fit

    light x=-5.3 y=3.2 z=-13.2 radius=8.5 brightness=1.0
    light x=5.3 y=3.2 z=-13.2 radius=8.5 brightness=1.0

    // South wall of the crypt, with an arched doorway at x -2.4..2.4. The
    // passage carries this wall over again, and the way through stands on its
    // far face at z -4.8.
    box   x0=-6.4 y0=0 z0=-6.4 x1=-2.4 y1=5.6 z1=-4.8 tex=stone_blocks
    box   x0=2.4 y0=0 z0=-6.4 x1=6.4 y1=5.6 z1=-4.8 tex=stone_blocks
    box   x0=-2.4 y0=5.6 z0=-6.4 x1=2.4 y1=6.4 z1=-4.8 tex=stone_blocks
    arch  axis=z a0=-6.4 a1=-4.8 c0=-2.4 c1=2.4 ybase=3.6 ytop=5.6 segs=5 tex=sandstone_brick bottom=sandstone_brick

    portal to=passage x0=-2.4 y0=0 z0=-4.8 x1=2.4 y1=5.6 z1=-4.8 dir=pz

    // The passage's lamp, so the doorway is lit the same from both sides
    light x=0 y=4.25 z=-2.4 radius=6 brightness=0.45

    tour x=0 y=1.4 z=-13 yaw=0 pitch=0
}

// ===========================================================================
// Passage down to the vault: x -2.4..2.4, z -4.8..0, ceiling 5.6. It is a
// short thing between two doorways, so most of what it holds is the two walls
// it shares, one at either end.
// ===========================================================================

area passage {
    // Floor and ceiling run out under both doorways, so this area is closed
    // right up to the far face of each of them
    box   x0=-4 y0=-0.8 z0=-6.4 x1=4 y1=0 z1=0 tex=floor_stone
    box   x0=-4 y0=5.6 z0=-6.4 x1=4 y1=6.4 z1=0 tex=stone_large
    box   x0=-4 y0=0 z0=-4.8 x1=-2.4 y1=5.6 z1=0 tex=brick_tan
    box   x0=2.4 y0=0 z0=-4.8 x1=4 y1=5.6 z1=0 tex=brick_tan

    // The crypt's south wall over again
    box   x0=-6.4 y0=0 z0=-6.4 x1=-2.4 y1=5.6 z1=-4.8 tex=stone_blocks
    box   x0=2.4 y0=0 z0=-6.4 x1=6.4 y1=5.6 z1=-4.8 tex=stone_blocks
    arch  axis=z a0=-6.4 a1=-4.8 c0=-2.4 c1=2.4 ybase=3.6 ytop=5.6 segs=5 tex=sandstone_brick bottom=sandstone_brick

    // The vault's north wall over again. Only the arch is wanted: the side
    // walls above already close this end, and so does the ceiling.
    arch  axis=z a0=-1.6 a1=0 c0=-2.4 c1=2.4 ybase=3.6 ytop=5.6 segs=5 tex=sandstone_brick bottom=sandstone_brick

    portal to=crypt x0=-2.4 y0=0 z0=-6.4 x1=2.4 y1=5.6 z1=-6.4 dir=nz
    portal to=vault x0=-2.4 y0=0 z0=0 x1=2.4 y1=5.6 z1=0 dir=pz

    light x=0 y=4.25 z=-2.4 radius=6 brightness=0.45

    // The lamps either side, so both doorways are lit the same from both sides
    light x=-5.3 y=3.2 z=-13.2 radius=8.5 brightness=1.0
    light x=5.3 y=3.2 z=-13.2 radius=8.5 brightness=1.0
    light x=-6.5 y=3 z=2.75 radius=9.5 brightness=0.46
    light x=6.5 y=3 z=2.75 radius=9.5 brightness=0.46

    tour x=0 y=1.4 z=-4.5 yaw=0 pitch=5.73
}

// ===========================================================================
// The vault: interior x -14.4..14.4, z 0..32. The lava lake sits at y -4.4,
// the stone bridge crosses it at y 0, and the ceiling is up at 16.
// ===========================================================================

area vault {
    // The lake, and the ledges at either end of it
    box   x0=-14.4 y0=-6.4 z0=3.2 x1=14.4 y1=-4.4 z1=27.2 tex=lava flow
    box   x0=-14.4 y0=-6.4 z0=0 x1=14.4 y1=0 z1=3.2 tex=floor_stone top=floor_stone scale=20
    box   x0=-14.4 y0=-6.4 z0=27.2 x1=14.4 y1=0 z1=32 tex=floor_stone top=floor_stone scale=20

    // The bridge across the lake
    box   x0=-2.4 y0=-6.4 z0=3.2 x1=2.4 y1=0 z1=27.2 tex=metal_riveted top=floor_stone scale=20

    // The ceiling is a gable running the length of the room: two slopes rising
    // from the tops of the side walls at 10.4 to a ridge down the middle at 16,
    // where the slab that caps the room sits on them. An arch of two segments is
    // exactly that pair of slopes.
    arch  axis=z a0=0 a1=32 c0=-14.4 c1=14.4 ybase=10.4 ytop=16 segs=2 tex=stone_large bottom=stone_large

    // That cap, and the walls behind everything else
    box   x0=-16 y0=16 z0=0 x1=16 y1=16.8 z1=33.6 tex=stone_large
    box   x0=-16 y0=-6.4 z0=0 x1=-14.4 y1=16 z1=6.4 tex=stone_blocks
    box   x0=-16 y0=-6.4 z0=10.4 x1=-14.4 y1=16 z1=14 tex=stone_blocks
    box   x0=-16 y0=-6.4 z0=18 x1=-14.4 y1=16 z1=21.6 tex=stone_blocks
    // This stretch of the west wall carries the way through to the monolith
    // chamber. The opening sits at ledge level in the far corner of the room, so
    // what you see from the bridge is a door in the corner rather than a stair
    // standing out in the open; the climb is all on the far side of it.
    box   x0=-16 y0=-6.4 z0=25.6 x1=-14.4 y1=16 z1=27.2 tex=stone_blocks
    box   x0=-16 y0=-6.4 z0=32 x1=-14.4 y1=16 z1=33.6 tex=stone_blocks
    box   x0=-16 y0=-6.4 z0=27.2 x1=-14.4 y1=0 z1=32 tex=stone_blocks top=floor_stone
    box   x0=-16 y0=5.6 z0=27.2 x1=-14.4 y1=16 z1=32 tex=stone_blocks
    arch  axis=x a0=-16 a1=-14.4 c0=27.2 c1=32 ybase=3.6 ytop=5.6 segs=4 tex=sandstone_brick bottom=sandstone_brick

    box   x0=14.4 y0=-6.4 z0=0 x1=16 y1=16 z1=33.6 tex=stone_blocks

    // North wall, with the arched way back to the passage. The doorway needs a
    // threshold: the ledge behind it starts at z 0.
    box   x0=-2.4 y0=-0.8 z0=-1.6 x1=2.4 y1=0 z1=0 tex=floor_stone top=floor_stone scale=20
    box   x0=-16 y0=-6.4 z0=-1.6 x1=-2.4 y1=16 z1=0 tex=stone_blocks
    box   x0=2.4 y0=-6.4 z0=-1.6 x1=16 y1=16 z1=0 tex=stone_blocks
    box   x0=-2.4 y0=5.6 z0=-1.6 x1=2.4 y1=16 z1=0 tex=stone_blocks
    arch  axis=z a0=-1.6 a1=0 c0=-2.4 c1=2.4 ybase=3.6 ytop=5.6 segs=5 tex=sandstone_brick bottom=sandstone_brick

    // South wall, with the arched way on to the reliquary. The doorway needs its
    // own floor: the wall pieces either side of it stop at the opening.
    box   x0=-3.2 y0=-2.4 z0=32 x1=3.2 y1=0 z1=33.6 tex=floor_stone top=floor_stone scale=20
    box   x0=-16 y0=-6.4 z0=32 x1=-3.2 y1=16 z1=33.6 tex=stone_blocks
    box   x0=3.2 y0=-6.4 z0=32 x1=16 y1=16 z1=33.6 tex=stone_blocks
    box   x0=-3.2 y0=7.2 z0=32 x1=3.2 y1=16 z1=33.6 tex=stone_blocks
    arch  axis=z a0=32 a1=33.6 c0=-3.2 c1=3.2 ybase=4.8 ytop=7.2 segs=5 tex=sandstone_brick bottom=sandstone_brick

    // --- Timber beams tying the roof across, one every 6.4 m ---
    //
    // They sit above the eaves, so each one runs out of one slope and into the
    // other, and nothing below them is high enough to touch. `turn` lays the grain
    // along the beam rather than across it.

    box   x0=-14.4 y0=11.4 z0=2.7 x1=14.4 y1=12.6 z1=3.7 tex=wood_dark turn
    box   x0=-14.4 y0=11.4 z0=9.1 x1=14.4 y1=12.6 z1=10.1 tex=wood_dark turn
    box   x0=-14.4 y0=11.4 z0=15.5 x1=14.4 y1=12.6 z1=16.5 tex=wood_dark turn
    box   x0=-14.4 y0=11.4 z0=21.9 x1=14.4 y1=12.6 z1=22.9 tex=wood_dark turn
    box   x0=-14.4 y0=11.4 z0=28.3 x1=14.4 y1=12.6 z1=29.3 tex=wood_dark turn

    // --- The west arcade: three lamps in arched recesses ---
    //
    // Each one is a pocket cut 0.8 m deep into the wall: the wall below and
    // above it, the back of the pocket, the lamp mounted on that back, and a
    // faceted arch
    // across the mouth. Nothing protrudes into the room.

    box   x0=-16 y0=-6.4 z0=6.4 x1=-14.4 y1=0 z1=10.4 tex=stone_blocks
    box   x0=-16 y0=5.6 z0=6.4 x1=-14.4 y1=16 z1=10.4 tex=stone_blocks
    box   x0=-16 y0=0 z0=6.4 x1=-15.2 y1=5.6 z1=10.4 tex=brick_tan
    box   x0=-15.2 y0=1.6 z0=7.6 x1=-15.1 y1=4.4 z1=9.2 tex=stone_blocks px=light_bank light=15 fit
    arch  axis=x a0=-15.2 a1=-14.4 c0=6.4 c1=10.4 ybase=4.4 ytop=5.6 segs=4 tex=sandstone_brick bottom=sandstone_brick

    box   x0=-16 y0=-6.4 z0=14 x1=-14.4 y1=0 z1=18 tex=stone_blocks
    box   x0=-16 y0=5.6 z0=14 x1=-14.4 y1=16 z1=18 tex=stone_blocks
    box   x0=-16 y0=0 z0=14 x1=-15.2 y1=5.6 z1=18 tex=brick_tan
    box   x0=-15.2 y0=1.6 z0=15.2 x1=-15.1 y1=4.4 z1=16.8 tex=stone_blocks px=light_bank light=15 fit
    arch  axis=x a0=-15.2 a1=-14.4 c0=14 c1=18 ybase=4.4 ytop=5.6 segs=4 tex=sandstone_brick bottom=sandstone_brick

    box   x0=-16 y0=-6.4 z0=21.6 x1=-14.4 y1=0 z1=25.6 tex=stone_blocks
    box   x0=-16 y0=5.6 z0=21.6 x1=-14.4 y1=16 z1=25.6 tex=stone_blocks
    box   x0=-16 y0=0 z0=21.6 x1=-15.2 y1=5.6 z1=25.6 tex=brick_tan
    box   x0=-15.2 y0=1.6 z0=22.8 x1=-15.1 y1=4.4 z1=24.4 tex=stone_blocks px=light_bank light=15 fit
    arch  axis=x a0=-15.2 a1=-14.4 c0=21.6 c1=25.6 ybase=4.4 ytop=5.6 segs=4 tex=sandstone_brick bottom=sandstone_brick

    light x=-14.8 y=3 z=8.4 radius=9.5 brightness=1.0
    light x=-14.8 y=3 z=16 radius=9.5 brightness=1.0
    light x=-14.8 y=3 z=23.6 radius=9.5 brightness=1.0

    // --- Buttresses along the west wall, angled where they meet it ---
    //
    // `nx` keeps the wall side at full height, so each one is deepest against the
    // wall and slopes away as it comes out over the lava, which is the way a
    // buttress carries a load

    ramp  x0=-14.4 y0=-4.4 z0=4.5 x1=-12.4 y1=4.5 z1=6.5 dir=nx tex=sandstone_brick
    ramp  x0=-14.4 y0=-4.4 z0=12.1 x1=-12.4 y1=4.5 z1=14.1 dir=nx tex=sandstone_brick
    ramp  x0=-14.4 y0=-4.4 z0=19.7 x1=-12.4 y1=4.5 z1=21.7 dir=nx tex=sandstone_brick

    // --- The east side: a plinth, a ramp climbing it, and the gallery above ---

    box   x0=9.6 y0=-6.4 z0=27.2 x1=14.4 y1=0 z1=32 tex=stone_blocks top=floor_stone

    // A slab under the ramp, so the foot of it has some thickness to it instead of
    // tapering away to nothing where it meets the ledge
    box   x0=9.6 y0=-0.75 z0=12.8 x1=14.4 y1=0 z1=27.2 tex=stone_blocks scale=20
    ramp  x0=9.6 y0=0 z0=12.8 x1=14.4 y1=6.4 z1=27.2 dir=nz tex=stone_blocks top=floor_stone scale=20

    box   x0=9.6 y0=-6.4 z0=3.2 x1=14.4 y1=6.4 z1=12.8 tex=stone_blocks top=floor_stone scale=20

    // The parapet along the gallery, with a gap to see over
    box   x0=8.8 y0=6.4 z0=3.2 x1=9.6 y1=8 z1=7.4 tex=sandstone_brick
    box   x0=8.8 y0=6.4 z0=10.6 x1=9.6 y1=8 z1=12.8 tex=sandstone_brick
    box   x0=8.8 y0=6.4 z0=7.4 x1=9.6 y1=7.2 z1=10.6 tex=sandstone_brick

    // Lamps set into the east wall above the gallery
    box   x0=14.2 y0=8 z0=6 x1=14.4 y1=9.6 z1=7.4 tex=brick_tan nx=light_square light=15 fit
    box   x0=14.2 y0=8 z0=9.8 x1=14.4 y1=9.6 z1=11.2 tex=brick_tan nx=light_square light=15 fit
    light x=13.8 y=8.75 z=6.7 radius=7.5 brightness=1.0
    light x=13.8 y=8.75 z=10.5 radius=7.5 brightness=1.0

    // A crate or two left on the gallery
    box   x0=10.5 y0=6.4 z0=4.5 x1=12.9 y1=8.8 z1=6.9 tex=crate_wood fit
    box   x0=10.8 y0=8.8 z0=5.1 x1=12.6 y1=10.6 z1=6.7 tex=crate_wood fit

    // --- What the lava throws up into the room ---
    //
    // These sit in the open air over the lake, clear of the bridge pier at x
    // -2.4..2.4 and of the east plinth at x 9.6: a lamp inside either one is walled
    // off from the room and lights nothing.
    //
    // The lake runs z 3.2..27.2, so they are spaced about its middle at 15.2. A
    // lamp nearer one end than the other lights that end's ledge harder, and since
    // the two ledges face each other across the room the difference is there to be
    // compared.

    light x=-7.2 y=-3.25 z=8 radius=14 brightness=0.44
    light x=7.2 y=-3.25 z=8 radius=14 brightness=0.44
    light x=-7.2 y=-3.25 z=15.2 radius=14 brightness=0.44
    light x=7.2 y=-3.25 z=15.2 radius=14 brightness=0.44
    light x=-7.2 y=-3.25 z=22.4 radius=14 brightness=0.44
    light x=7.2 y=-3.25 z=22.4 radius=14 brightness=0.44
    light x=-7.5 y=-3.25 z=11.6 radius=12 brightness=0.34
    light x=7.5 y=-3.25 z=11.6 radius=12 brightness=0.34
    light x=-7.5 y=-3.25 z=18.8 radius=12 brightness=0.34
    light x=7.5 y=-3.25 z=18.8 radius=12 brightness=0.34

    // The glow the lake throws up onto the bridge and the ledges. These sit above
    // the deck on purpose: a floor takes nothing from a lamp underneath it. They
    // stand almost on top of the deck, so what they mostly light is the deck, and
    // they are the one thing that decides how bright it reads.
    light x=0 y=2.25 z=7.5 radius=14 brightness=0.42
    light x=0 y=2.25 z=15 radius=14 brightness=0.42
    light x=0 y=2.25 z=22.5 radius=14 brightness=0.42

    // High fill under the eaves. Mirrored: a single lamp to one side at each end
    // leans the whole bridge that way, and the lean reads as a mistake because
    // nothing up there is visible to explain it.
    light x=-7.5 y=10.5 z=12 radius=15.5 brightness=0.13
    light x=7.5 y=10.5 z=12 radius=15.5 brightness=0.13
    light x=-7.5 y=10.5 z=20.5 radius=15.5 brightness=0.13
    light x=7.5 y=10.5 z=20.5 radius=15.5 brightness=0.13
    light x=-6.5 y=3 z=2.75 radius=9.5 brightness=0.46
    light x=6.5 y=3 z=2.75 radius=9.5 brightness=0.46
    light x=-6.5 y=3 z=29.5 radius=9.5 brightness=0.46
    light x=6.5 y=3 z=29.5 radius=9.5 brightness=0.46

    // The lamps of the rooms next door, for the walls this one shares with them
    light x=0 y=4.25 z=-2.4 radius=6 brightness=0.45
    light x=-5.3 y=3.2 z=34.7 radius=8 brightness=0.9
    light x=5.3 y=3.2 z=34.7 radius=8 brightness=0.9
    light x=-17.5 y=3.5 z=29.6 radius=8 brightness=0.55

    portal to=passage x0=-2.4 y0=0 z0=-1.6 x1=2.4 y1=5.6 z1=-1.6 dir=nz
    portal to=reliquary x0=-3.2 y0=0 z0=33.6 x1=3.2 y1=7.2 z1=33.6 dir=pz
    portal to=stairs x0=-16 y0=0 z0=27.2 x1=-16 y1=5.6 z1=32 dir=nx

    tour x=0 y=1.4 z=2 yaw=0 pitch=0
    tour x=0 y=1.4 z=10.5 yaw=28.65 pitch=-5.73
    tour x=0 y=1.4 z=19 yaw=-34.38 pitch=-8.59
    tour x=-1.5 y=1.4 z=27 yaw=51.57 pitch=2.86
    tour x=12.5 y=7.8 z=22.5 yaw=-108.86 pitch=-12.61
    tour x=12 y=7.8 z=15.5 yaw=-100.27 pitch=-20.05
    tour x=0 y=3 z=13 yaw=0 pitch=-28.65
}

// ===========================================================================
// The reliquary: interior x -6.4..6.4, z 33.6..44.8, ceiling 7.2. A sunken
// pool of lava in the middle of the floor lights the room from below.
// ===========================================================================

area reliquary {
    // The shell reaches back under the doorway to z 32, where the vault begins
    box   x0=-8 y0=7.2 z0=32 x1=8 y1=8 z1=46.4 tex=stone_large
    box   x0=-8 y0=0 z0=32 x1=-6.4 y1=7.2 z1=46.4 tex=brick_blue
    box   x0=6.4 y0=0 z0=32 x1=8 y1=7.2 z1=46.4 tex=brick_blue
    box   x0=-8 y0=0 z0=44.8 x1=8 y1=7.2 z1=46.4 tex=brick_blue

    // The floor, in four pieces around the pool
    box   x0=-8 y0=-2.4 z0=32 x1=8 y1=0 z1=37.6 tex=floor_checker
    box   x0=-8 y0=-2.4 z0=42.4 x1=8 y1=0 z1=46.4 tex=floor_checker
    box   x0=-8 y0=-2.4 z0=37.6 x1=-3.2 y1=0 z1=42.4 tex=floor_checker
    box   x0=3.2 y0=-2.4 z0=37.6 x1=8 y1=0 z1=42.4 tex=floor_checker

    // The vault's south wall over again, the doorway's own floor included
    box   x0=-3.2 y0=-2.4 z0=32 x1=3.2 y1=0 z1=33.6 tex=floor_stone top=floor_stone scale=20
    box   x0=-8 y0=-2.4 z0=32 x1=-3.2 y1=7.2 z1=33.6 tex=stone_blocks
    box   x0=3.2 y0=-2.4 z0=32 x1=8 y1=7.2 z1=33.6 tex=stone_blocks
    arch  axis=z a0=32 a1=33.6 c0=-3.2 c1=3.2 ybase=4.8 ytop=7.2 segs=5 tex=sandstone_brick bottom=sandstone_brick

    // The pool itself, and the rough rock it has eaten into. The surface rides
    // the wave, which takes it a WAVE_AMP down each way, so it sits that much
    // above the underside of the floor rather than flush with it: level with it,
    // the down-swing would pull the lava clear of the rim and open a gap all the
    // way round.
    box   x0=-3.2 y0=-4 z0=37.6 x1=3.2 y1=-2 z1=42.4 tex=lava_swirl flow
    box   x0=-3.2 y0=-4.2 z0=37.4 x1=3.2 y1=-4 z1=42.6 tex=rock_craggy

    // An eight-sided pedestal standing in the pool
    prism cx=0 cz=40 radius=1.8 y0=-2.4 y1=2.4 sides=8 rot=22.5 tex=sandstone_brick top=sandstone_brick

    light x=0 y=-1 z=40 radius=11.5 brightness=0.85
    light x=0 y=5.25 z=35.75 radius=6.5 brightness=0.3

    // Torch niches either side of the door back out
    box   x0=-6.4 y0=2.4 z0=34 x1=-5.6 y1=4 z1=35.4 tex=brick_blue px=light_bank light=15 fit
    box   x0=5.6 y0=2.4 z0=34 x1=6.4 y1=4 z1=35.4 tex=brick_blue nx=light_bank light=15 fit
    light x=-5.3 y=3.2 z=34.7 radius=8 brightness=0.9
    light x=5.3 y=3.2 z=34.7 radius=8 brightness=0.9

    // The vault's lamps nearest the doorway, for its copy of the wall
    light x=-6.5 y=3 z=29.5 radius=9.5 brightness=0.46
    light x=6.5 y=3 z=29.5 radius=9.5 brightness=0.46

    portal to=vault x0=-3.2 y0=0 z0=32 x1=3.2 y1=7.2 z1=32 dir=nz

    tour x=5.375 y=2.15 z=34.5 yaw=-25.78 pitch=-1.15
}

// ===========================================================================
// The way up to the monolith chamber: a low corridor leaving the far corner of
// the vault's ledge, and a stair beyond it climbing 6.4 m in a shaft that opens
// out above you.
//
// The corridor is as wide as the ledge it leaves and the height of a door. The
// shaft it runs into is wider again and more than twice as tall, so the space
// opens out around you and over your head as the stair starts to climb.
// ===========================================================================

area stairs {
    box   x0=-19.2 y0=-1.6 z0=27.2 x1=-16 y1=0 z1=32 tex=stone_blocks top=floor_stone
    box   x0=-19.2 y0=5.6 z0=27.2 x1=-16 y1=14.4 z1=32 tex=iron_brick
    box   x0=-19.2 y0=-1.6 z0=25.6 x1=-16 y1=14.4 z1=27.2 tex=iron_brick
    box   x0=-19.2 y0=-1.6 z0=32 x1=-16 y1=14.4 z1=33.6 tex=iron_brick

