    arch  axis=x a0=-16 a1=-14.4 c0=27.2 c1=32 ybase=3.6 ytop=5.6 segs=4 tex=sandstone_brick bottom=sandstone_brick

    // The monolith chamber's east wall over again, at the top of the climb
    box   x0=-33.6 y0=4.8 z0=26.4 x1=-32 y1=6.4 z1=32.8 tex=iron_brick top=floor_checker
    box   x0=-33.6 y0=4.8 z0=24.8 x1=-32 y1=59.2 z1=26.4 tex=iron_brick
    box   x0=-33.6 y0=4.8 z0=32.8 x1=-32 y1=59.2 z1=34.4 tex=iron_brick
    box   x0=-33.6 y0=12 z0=26.4 x1=-32 y1=59.2 z1=32.8 tex=iron_brick
    arch  axis=x a0=-33.6 a1=-32 c0=26.4 c1=32.8 ybase=10 ytop=12 segs=4 tex=sandstone_brick bottom=sandstone_brick

    // Sixteen steps of 0.4 m, climbing west from x -19.2 to the sill at -32.
