    box   x0=-32 y0=-1.6 z0=26.4 x1=-31.2 y1=6.4 z1=32.8 tex=stone_blocks top=floor_stone

    // The way in wants enough light to walk by, and no more
    light x=-17.5 y=3.5 z=29.6 radius=8 brightness=0.55
    light x=-22.5 y=6 z=29.6 radius=8.5 brightness=0.45
    light x=-27 y=8 z=29.6 radius=8.5 brightness=0.45
    light x=-31.25 y=11 z=29.6 radius=8 brightness=0.40

