// ===========================================================================
// The monolith chamber: interior x -84.8..-33.6, z 4..55.2, floor 6.4,
// ceiling 57.6. A 51.2 m cube, hung off the west wall of the vault and reached
// from the far corner of the ledge behind the lava.
//
// The crosses stop 9.6 m short of the ceiling, which is a good deal more than
// they stand clear of the floor: the roof wants dark above them rather than
// the tops of the arms crowding it.
//
// The door is left the size it always was, so the room opens out all at once
// as you step through it rather than being announced by its entrance.
//
// The room is lit only by what the crosses give off, which is little, by the
// well in the roof, and by one lamp inside the door. Everything else is meant
// to be lost in the dark.
// ===========================================================================

area monolith {
    // --- Shell ---

    box   x0=-86.4 y0=4.8 z0=2.4 x1=-32 y1=6.4 z1=56.8 tex=iron_brick top=floor_checker

    box   x0=-33.6 y0=4.8 z0=2.4 x1=-32 y1=59.2 z1=26.4 tex=iron_brick
    box   x0=-33.6 y0=4.8 z0=32.8 x1=-32 y1=59.2 z1=56.8 tex=iron_brick
    box   x0=-33.6 y0=12 z0=26.4 x1=-32 y1=59.2 z1=32.8 tex=iron_brick
    arch  axis=x a0=-33.6 a1=-32 c0=26.4 c1=32.8 ybase=10 ytop=12 segs=4 tex=sandstone_brick bottom=sandstone_brick

    // --- The three crosses ---
    //
    // Each of the west, north and south walls is built in two layers: a back
    // plate, and a front layer 0.8 m proud of it laid out as eight pieces around
    // a cross shaped void. The upright stands 35.2 m and the bar reaches 25.6 m
    // across, both cut 6.4 m thick, so what shows is a thin figure drawn on a
    // broad wall rather than a blocky one. The bar sits a little over a quarter
    // of the way up the
    // upright rather than the same distance down from the top, which turns the
    // cross over.
    //
    // The bar is placed in whole lozenge rows. A row is 0.8 m -- a quarter of the
    // 3.2 m a panel fits -- so the bar can only be moved by multiples of 0.8 m
    // without its rows falling out of step with the upright's.
    //
    // The void is filled with lamp panels laid on the back plate, so each cross
    // reads as a slot of red light rather than a shadow. Those panels are cut into
    // 3.2 m squares, one per texture, and each is marked `fit`: the lamp texture is
    // 128 texels across and lays its eight lozenges out on a 64 by 32 texel grid
    // inside that, so a panel whose edges miss those lines slices the lozenges at
    // its ends. A limb is two panels across at this size, and the void is filled
    // two columns wide rather than one. The room is centred on z 29.6 and x -59.2,
    // neither of which the grid divides, so tiling by world position cannot be
    // made to land -- `fit` maps one whole copy across each square instead and
    // puts the cut where the panels already end.
    //
    // The upright and the arms are cut as separate squares that meet rather than
    // overlap, so no two lamp faces are coplanar.

    // West wall
    box   x0=-86.4 y0=4.8 z0=2.4 x1=-85.6 y1=59.2 z1=56.8 tex=iron_brick

    box   x0=-85.6 y0=6.4 z0=4 x1=-84.8 y1=12.8 z1=55.2 tex=iron_brick
    box   x0=-85.6 y0=48 z0=4 x1=-84.8 y1=57.6 z1=55.2 tex=iron_brick
    box   x0=-85.6 y0=12.8 z0=4 x1=-84.8 y1=19.2 z1=26.4 tex=iron_brick
    box   x0=-85.6 y0=12.8 z0=32.8 x1=-84.8 y1=19.2 z1=55.2 tex=iron_brick
    box   x0=-85.6 y0=19.2 z0=4 x1=-84.8 y1=25.6 z1=16.8 tex=iron_brick
    box   x0=-85.6 y0=19.2 z0=42.4 x1=-84.8 y1=25.6 z1=55.2 tex=iron_brick
    box   x0=-85.6 y0=25.6 z0=4 x1=-84.8 y1=48 z1=26.4 tex=iron_brick
    box   x0=-85.6 y0=25.6 z0=32.8 x1=-84.8 y1=48 z1=55.2 tex=iron_brick

    box   x0=-85.6 y0=12.8 z0=26.4 x1=-85.5 y1=16 z1=29.6 tex=iron_brick px=light_strip_red light=15 fit
    box   x0=-85.6 y0=16 z0=26.4 x1=-85.5 y1=19.2 z1=29.6 tex=iron_brick px=light_strip_red light=15 fit
    box   x0=-85.6 y0=19.2 z0=26.4 x1=-85.5 y1=22.4 z1=29.6 tex=iron_brick px=light_strip_red light=15 fit
    box   x0=-85.6 y0=22.4 z0=26.4 x1=-85.5 y1=25.6 z1=29.6 tex=iron_brick px=light_strip_red light=15 fit
    box   x0=-85.6 y0=25.6 z0=26.4 x1=-85.5 y1=28.8 z1=29.6 tex=iron_brick px=light_strip_red light=15 fit
    box   x0=-85.6 y0=28.8 z0=26.4 x1=-85.5 y1=32 z1=29.6 tex=iron_brick px=light_strip_red light=15 fit
    box   x0=-85.6 y0=32 z0=26.4 x1=-85.5 y1=35.2 z1=29.6 tex=iron_brick px=light_strip_red light=15 fit
    box   x0=-85.6 y0=35.2 z0=26.4 x1=-85.5 y1=38.4 z1=29.6 tex=iron_brick px=light_strip_red light=15 fit
    box   x0=-85.6 y0=38.4 z0=26.4 x1=-85.5 y1=41.6 z1=29.6 tex=iron_brick px=light_strip_red light=15 fit
    box   x0=-85.6 y0=41.6 z0=26.4 x1=-85.5 y1=44.8 z1=29.6 tex=iron_brick px=light_strip_red light=15 fit
    box   x0=-85.6 y0=44.8 z0=26.4 x1=-85.5 y1=48 z1=29.6 tex=iron_brick px=light_strip_red light=15 fit

    box   x0=-85.6 y0=12.8 z0=29.6 x1=-85.5 y1=16 z1=32.8 tex=iron_brick px=light_strip_red light=15 fit
    box   x0=-85.6 y0=16 z0=29.6 x1=-85.5 y1=19.2 z1=32.8 tex=iron_brick px=light_strip_red light=15 fit
    box   x0=-85.6 y0=19.2 z0=29.6 x1=-85.5 y1=22.4 z1=32.8 tex=iron_brick px=light_strip_red light=15 fit
    box   x0=-85.6 y0=22.4 z0=29.6 x1=-85.5 y1=25.6 z1=32.8 tex=iron_brick px=light_strip_red light=15 fit
    box   x0=-85.6 y0=25.6 z0=29.6 x1=-85.5 y1=28.8 z1=32.8 tex=iron_brick px=light_strip_red light=15 fit
    box   x0=-85.6 y0=28.8 z0=29.6 x1=-85.5 y1=32 z1=32.8 tex=iron_brick px=light_strip_red light=15 fit
    box   x0=-85.6 y0=32 z0=29.6 x1=-85.5 y1=35.2 z1=32.8 tex=iron_brick px=light_strip_red light=15 fit
    box   x0=-85.6 y0=35.2 z0=29.6 x1=-85.5 y1=38.4 z1=32.8 tex=iron_brick px=light_strip_red light=15 fit
    box   x0=-85.6 y0=38.4 z0=29.6 x1=-85.5 y1=41.6 z1=32.8 tex=iron_brick px=light_strip_red light=15 fit
    box   x0=-85.6 y0=41.6 z0=29.6 x1=-85.5 y1=44.8 z1=32.8 tex=iron_brick px=light_strip_red light=15 fit
    box   x0=-85.6 y0=44.8 z0=29.6 x1=-85.5 y1=48 z1=32.8 tex=iron_brick px=light_strip_red light=15 fit

    box   x0=-85.6 y0=19.2 z0=16.8 x1=-85.5 y1=22.4 z1=20 tex=iron_brick px=light_strip_red light=15 fit
    box   x0=-85.6 y0=19.2 z0=20 x1=-85.5 y1=22.4 z1=23.2 tex=iron_brick px=light_strip_red light=15 fit
    box   x0=-85.6 y0=19.2 z0=23.2 x1=-85.5 y1=22.4 z1=26.4 tex=iron_brick px=light_strip_red light=15 fit
    box   x0=-85.6 y0=19.2 z0=32.8 x1=-85.5 y1=22.4 z1=36 tex=iron_brick px=light_strip_red light=15 fit
    box   x0=-85.6 y0=19.2 z0=36 x1=-85.5 y1=22.4 z1=39.2 tex=iron_brick px=light_strip_red light=15 fit
    box   x0=-85.6 y0=19.2 z0=39.2 x1=-85.5 y1=22.4 z1=42.4 tex=iron_brick px=light_strip_red light=15 fit

    box   x0=-85.6 y0=22.4 z0=16.8 x1=-85.5 y1=25.6 z1=20 tex=iron_brick px=light_strip_red light=15 fit
    box   x0=-85.6 y0=22.4 z0=20 x1=-85.5 y1=25.6 z1=23.2 tex=iron_brick px=light_strip_red light=15 fit
    box   x0=-85.6 y0=22.4 z0=23.2 x1=-85.5 y1=25.6 z1=26.4 tex=iron_brick px=light_strip_red light=15 fit
    box   x0=-85.6 y0=22.4 z0=32.8 x1=-85.5 y1=25.6 z1=36 tex=iron_brick px=light_strip_red light=15 fit
    box   x0=-85.6 y0=22.4 z0=36 x1=-85.5 y1=25.6 z1=39.2 tex=iron_brick px=light_strip_red light=15 fit
    box   x0=-85.6 y0=22.4 z0=39.2 x1=-85.5 y1=25.6 z1=42.4 tex=iron_brick px=light_strip_red light=15 fit

    // North wall
    box   x0=-86.4 y0=4.8 z0=2.4 x1=-32 y1=59.2 z1=3.2 tex=iron_brick

    box   x0=-84.8 y0=6.4 z0=3.2 x1=-33.6 y1=12.8 z1=4 tex=iron_brick
    box   x0=-84.8 y0=48 z0=3.2 x1=-33.6 y1=57.6 z1=4 tex=iron_brick
    box   x0=-84.8 y0=12.8 z0=3.2 x1=-62.4 y1=19.2 z1=4 tex=iron_brick
    box   x0=-56 y0=12.8 z0=3.2 x1=-33.6 y1=19.2 z1=4 tex=iron_brick
    box   x0=-84.8 y0=19.2 z0=3.2 x1=-72 y1=25.6 z1=4 tex=iron_brick
    box   x0=-46.4 y0=19.2 z0=3.2 x1=-33.6 y1=25.6 z1=4 tex=iron_brick
    box   x0=-84.8 y0=25.6 z0=3.2 x1=-62.4 y1=48 z1=4 tex=iron_brick
    box   x0=-56 y0=25.6 z0=3.2 x1=-33.6 y1=48 z1=4 tex=iron_brick

    box   x0=-62.4 y0=12.8 z0=3.2 x1=-59.2 y1=16 z1=3.3 tex=iron_brick pz=light_strip_red light=15 fit
    box   x0=-62.4 y0=16 z0=3.2 x1=-59.2 y1=19.2 z1=3.3 tex=iron_brick pz=light_strip_red light=15 fit
