    //
    // A slab of rough rock on a low plinth, 1 by 3 by 9, stood square in the middle
    // of the room with its broad face to the door. The crosses now stand clear of
    // its top, so it reads against them rather than over them.

    box   x0=-64 y0=6.4 z0=23.6 x1=-54.4 y1=8.8 z1=35.6 tex=rock_slate
